python - <<'PY'
import numpy as np
from PIL import Image
for tag in ['initial','current','latest']:
 p=f'/app/output/{tag}'
 try:
  im=np.asarray(Image.open(p+'/last/topview.jpg')); d=np.load(p+'/depth_topview.npy')[0]
  print(tag,'shaft depths',[(xy,float(d[xy[1],xy[0]]),im[xy[1],xy[0]].tolist()) for xy in [(120,123),(140,123),(155,123),(170,115)]])
 except Exception as e: print(tag,e)
PY

